with t as (select c.table_schema s,c.table_name n from information_schema.columns c join information_schema.tables tt on tt.table_schema=c.table_schema and tt.table_name=c.table_name and tt.table_type='BASE TABLE' where c.column_name='refresh_run_id' and c.table_schema in ('costing','public') and c.table_name<>'default_volume_cap_log'), f as (select s,n,(xpath('/row/x/text()',query_to_xml(format('select count(*)||'':''||coalesce(md5(string_agg(md5(%s),'''' order by md5(%s))),''-'') x from %I.%I t where refresh_run_id=122', case when n='sku_sales_allocation_basis_snapshot' then 'regexp_replace(t::text,'',\)$'','')'')' else 't::text' end, case when n='sku_sales_allocation_basis_snapshot' then 'regexp_replace(t::text,'',\)$'','')'')' else 't::text' end,s,n),false,true,'')))[1]::text v from t) select count(*) n, sum(split_part(v,':',1)::bigint) rows, md5(string_agg(s||'.'||n||'='||v,'|' order by s,n)) fp, (select md5(r::text) from costing.costing_refresh_run r where id=122) runrow, (select count(*) from costing.default_volume_cap_log where refresh_run_id=122) caplog122 from f
